css:
/* Review slider: a centred heading over a rail of review cards, five in view, with a thin progress bar on top
   that shows where the rail has scrolled to. Cards scroll by touch, trackpad, drag, arrow keys or the bar. */
[data-bz-node="rs-band"] { background: #003652; color: #fff; padding-block: 78px 80px; }
[data-bz-node="rs-band"] > .bz-container { max-width: calc(min(90vw, 1440px) + 32px); }
[data-bz-section="review-slider"] .bz-block { padding-block: 0; }
[data-bz-section="review-slider"] h2 { margin: 0 0 67px; text-align: center; color: #fff; font: 700 1.88rem / 1.2 var(--font-heading); letter-spacing: 0; }
[data-bz-section="review-slider"] [data-bz-node="rs-wrap"] { --rs-w: 33.33%; --rs-x: 0%; position: relative; padding-top: 8px; }
[data-bz-section="review-slider"] [data-bz-node="rs-wrap"]::before { content: ""; position: absolute; left: 0; right: 0; top: 0; height: 8px; border-radius: 8px 8px 0 0; background: #b0babf; }
[data-bz-section="review-slider"] [data-bz-node="rs-wrap"]::after { content: ""; position: absolute; top: 0; height: 8px; left: var(--rs-x); width: var(--rs-w); border-radius: 8px 0 0 0; background: #0093dd; }
[data-bz-section="review-slider"] [data-bz-node="rs-rail"] { --bz-slide-gap: 20px; --bz-slide: calc((100% - 80px) / 5); display: flex; gap: 20px; margin: 0; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none; padding: 0; cursor: grab; }
[data-bz-section="review-slider"] [data-bz-node="rs-rail"]::-webkit-scrollbar { display: none; }
[data-bz-section="review-slider"] [data-bz-node="rs-rail"].is-dragging { cursor: grabbing; scroll-snap-type: none; user-select: none; }
[data-bz-section="review-slider"] [data-bz-node="rs-rail"] > .bz-col { flex: 0 0 var(--bz-slide); grid-column: auto; min-width: 0; position: relative; box-sizing: border-box; min-height: 321px; padding: 24px 33px 40px; background: #ebf8ff; border-radius: 0 0 14px 14px; scroll-snap-align: start; display: flex; flex-direction: column; }
[data-bz-section="review-slider"] [data-bz-node^="rs-name"] { padding-right: 38px; }
[data-bz-section="review-slider"] [data-bz-node^="rs-name"] .bz-container, [data-bz-section="review-slider"] [data-bz-node^="rs-stars"] .bz-container, [data-bz-section="review-slider"] [data-bz-node^="rs-text"] .bz-container, [data-bz-section="review-slider"] [data-bz-node^="rs-g"] .bz-container { padding: 0; }
[data-bz-section="review-slider"] h3 { margin: 0; font: 700 1.425rem / 34px var(--font-heading); color: #003652; letter-spacing: 0; }
[data-bz-section="review-slider"] [data-bz-node^="rs-g"] { position: absolute; top: 26px; right: 33px; width: 27px; height: 27px; }
[data-bz-section="review-slider"] [data-bz-node^="rs-g"] .bz-figure { margin: 0; }
[data-bz-section="review-slider"] [data-bz-node^="rs-g"] img { display: block; width: 27px; height: 27px; max-width: none; border-radius: 0; }
[data-bz-section="review-slider"] [data-bz-node^="rs-stars"] .bz-text p { margin: 14px 0 0; font: 400 0.8rem / 12px var(--font-body); letter-spacing: 3px; color: #ffcd00; max-width: none; }
[data-bz-section="review-slider"] [data-bz-node^="rs-text"] { margin: 33px -33px 0; border-top: 1px solid #dbf2ff; flex: 1; }
[data-bz-section="review-slider"] [data-bz-node^="rs-text"] .bz-text p { margin: 0; padding: 28px 26px 0 33px; font: 400 0.94rem / 19px var(--font-body); color: #003652; max-width: none; }
@media (max-width: 1100px) { [data-bz-section="review-slider"] [data-bz-node="rs-rail"] { --bz-slide: calc((100% - 40px) / 3); } }
@media (max-width: 760px) { [data-bz-section="review-slider"] [data-bz-node="rs-rail"] { --bz-slide: calc((100% - 20px) / 2); } }
@media (max-width: 520px) { [data-bz-section="review-slider"] [data-bz-node="rs-rail"] { --bz-slide: 82%; } [data-bz-node="rs-band"] { padding-block: 48px; } [data-bz-section="review-slider"] h2 { font-size: 1.375rem; margin-bottom: 40px; } }

js:
/* Review slider: the bar on top follows the rail. It is as wide as the share of the rail you can see and moves as
   you scroll. Click or drag the bar to move the rail, and drag the cards with the mouse. With no script
   the rail still scrolls by touch and the bar rests at the left. */
(function () {
  document.querySelectorAll('[data-bz-section="review-slider"]').forEach(function (root) {
    if (root.__bzRS) return;
    root.__bzRS = true;
    var wrap = root.querySelector('[data-bz-node="rs-wrap"]');
    var rail = root.querySelector('[data-bz-node="rs-rail"]');
    if (!wrap || !rail) return;
    function paint() {
      var total = rail.scrollWidth, view = rail.clientWidth;
      if (!total || total <= view + 1) { wrap.style.setProperty('--rs-w', '100%'); wrap.style.setProperty('--rs-x', '0%'); return; }
      var w = view / total * 100;
      var x = rail.scrollLeft / total * 100;
      wrap.style.setProperty('--rs-w', w.toFixed(2) + '%');
      wrap.style.setProperty('--rs-x', Math.min(100 - w, x).toFixed(2) + '%');
    }
    rail.addEventListener('scroll', paint, { passive: true });
    window.addEventListener('resize', paint);
    paint();
    // the bar: a press in its 8px strip moves the rail to that point, and dragging keeps moving it
    function scrub(e) {
      var r = wrap.getBoundingClientRect();
      var f = Math.max(0, Math.min(1, (e.clientX - r.left) / r.width));
      rail.scrollLeft = f * rail.scrollWidth - rail.clientWidth / 2;
    }
    var scrubbing = false;
    wrap.addEventListener('pointerdown', function (e) {
      if (e.clientY - wrap.getBoundingClientRect().top > 12) return;
      scrubbing = true; scrub(e);
      try { wrap.setPointerCapture(e.pointerId); } catch (x) {}
    });
    wrap.addEventListener('pointermove', function (e) { if (scrubbing) scrub(e); });
    wrap.addEventListener('pointerup', function () { scrubbing = false; });
    wrap.addEventListener('pointercancel', function () { scrubbing = false; });
    // drag the cards with a mouse (touch already scrolls natively)
    var down = null, moved = false;
    rail.addEventListener('pointerdown', function (e) {
      if (e.pointerType !== 'mouse' || e.button !== 0) return;
      down = { x: e.clientX, left: rail.scrollLeft }; moved = false;
    });
    window.addEventListener('pointermove', function (e) {
      if (!down) return;
      var dx = e.clientX - down.x;
      if (!moved && Math.abs(dx) > 4) { moved = true; rail.classList.add('is-dragging'); }
      if (moved) rail.scrollLeft = down.left - dx;
    });
    window.addEventListener('pointerup', function () {
      if (!down) return;
      down = null;
      if (moved) { rail.classList.remove('is-dragging'); }
    });
  });
})();
